package ru.kstolu.app;
import android.app.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.lang.reflect.*;import java.io.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,qualifiers="w390dp-h844dp-mdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class PantryUiTest {
 private org.robolectric.android.controller.ActivityController<MainActivity> controller;private MainActivity host;
 @Before public void setup(){ApiClient.configureForTests(url->{throw new AssertionError("No network: "+url);});controller=Robolectric.buildActivity(MainActivity.class).setup();host=controller.get();}
 @After public void close(){controller.pause().stop().destroy();ApiClient.restoreTransport();}
 private Object call(String name,Class<?> type,Object value)throws Exception{Method m=MainActivity.class.getDeclaredMethod(name,type);m.setAccessible(true);return m.invoke(host,value);}
 private void call(String name)throws Exception{Method m=MainActivity.class.getDeclaredMethod(name);m.setAccessible(true);m.invoke(host);}
 private TextView find(View v,String s){if(v instanceof TextView&&((TextView)v).getText().toString().equals(s))return (TextView)v;if(v instanceof ViewGroup){for(int i=0;i<((ViewGroup)v).getChildCount();i++){TextView r=find(((ViewGroup)v).getChildAt(i),s);if(r!=null)return r;}}return null;}
 private JSONObject snapshot()throws Exception{return new JSONObject("{\"portions\":2,\"currency\":\"RUB\",\"recipe\":{\"status\":\"ok\",\"title\":\"Томаты с рисом\",\"description\":\"Горячий рис с томатами\",\"servings\":2,\"prep_minutes\":5,\"cook_minutes\":10,\"pantry\":{\"products\":[\"Томаты\",\"Рис\"]},\"difficulty\":{\"level\":\"easy\",\"reasons\":[\"Одна кастрюля\"]},\"ingredients\":[{\"name\":\"Томаты\",\"amount\":200,\"unit\":\"g\",\"availability\":\"present\",\"price\":{\"quantity\":1000,\"low\":120,\"high\":400,\"source\":\"estimate\"}},{\"name\":\"Рис\",\"amount\":100,\"unit\":\"g\",\"availability\":\"present\",\"price\":null},{\"name\":\"Вода\",\"amount\":300,\"unit\":\"ml\",\"availability\":\"basic\",\"price\":null}],\"steps\":[{\"title\":\"Сварите рис\",\"body\":\"Варите по упаковке. Добавьте томаты.\"}],\"warnings\":[]}}");}
 private void screenshot(View v,String name)throws Exception{v.measure(View.MeasureSpec.makeMeasureSpec(390,1073741824),View.MeasureSpec.makeMeasureSpec(844,1073741824));v.layout(0,0,390,844);Shadows.shadowOf(Looper.getMainLooper()).idle();v.measure(View.MeasureSpec.makeMeasureSpec(390,1073741824),View.MeasureSpec.makeMeasureSpec(844,1073741824));v.layout(0,0,390,844);Bitmap b=Bitmap.createBitmap(390,844,Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));File dir=new File("build/visual-qa-1.2.0");dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
 @Test public void recognitionOpensEditablePersistentListWithoutSecondRequest()throws Exception{call("acceptSelection",Object.class,new JSONObject("{\"kind\":\"inventory\",\"status\":\"ok\",\"products\":[\"Томаты\",\"Сыр\"],\"receiptPrices\":[],\"region\":\"Россия\",\"currency\":\"RUB\"}"));View root=host.getWindow().getDecorView();assertNotNull(find(root,"Проверьте продукты"));assertNotNull(find(root,"Томаты"));assertNotNull(find(root,"Только из моих продуктов"));assertTrue(host.getSharedPreferences("settings",0).contains("reviewedInventory"));screenshot(root,"review-products");find(root,"Томаты").performClick();AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertEquals("Название продукта",org.robolectric.Shadows.shadowOf(d).getTitle());d.dismiss();call("home");call("reviewProducts");assertNotNull(find(host.getWindow().getDecorView(),"Сыр"));}
 @Test public void kitchenSavesImmediatelyAndRestores()throws Exception{call("settings");View root=host.getWindow().getDecorView();assertNotNull(find(root,"Моя кухонная техника"));find(root,"Духовка").performClick();assertTrue(host.getSharedPreferences("settings",0).getStringSet("equipment",java.util.Collections.emptySet()).contains("oven"));call("home");call("settings");assertNotNull(find(host.getWindow().getDecorView(),"✓ Духовка"));screenshot(host.getWindow().getDecorView(),"kitchen-settings");}
 @Test public void priceAvailabilityAndDifficultyDoNotInventMissingData()throws Exception{JSONObject r=snapshot().getJSONObject("recipe");assertEquals("Есть 2 из 2 ингредиентов · + базовые",RecipeFacts.coverage(r));assertEquals("Просто · Одна кастрюля",RecipeFacts.difficulty(r));RecipeFacts.priceDetails(host,r,2,"RUB");AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertTrue(org.robolectric.Shadows.shadowOf(d).getMessage().toString().contains("Рис: не учтён"));d.dismiss();r.remove("pantry");r.remove("difficulty");assertEquals("",RecipeFacts.coverage(r));assertEquals("",RecipeFacts.difficulty(r));}
 @Test public void wakeScreenOnlyWhileCookingNotDoneOrOutside()throws Exception{InlineCooking cooking=new InlineCooking(host,snapshot());host.setContentView(cooking);assertTrue("attached",cooking.getKeepScreenOn());find(cooking,"Готово ✓").performClick();Shadows.shadowOf(Looper.getMainLooper()).idleFor(java.time.Duration.ofMillis(500));assertFalse("done",cooking.getKeepScreenOn());find(cooking,"Вернуться к шагам").performClick();Shadows.shadowOf(Looper.getMainLooper()).idleFor(java.time.Duration.ofMillis(500));assertTrue("back",cooking.getKeepScreenOn());cooking.suspendTimer();assertFalse("pause",cooking.getKeepScreenOn());cooking.resumeTimer();assertTrue("resume",cooking.getKeepScreenOn());host.setContentView(new TextView(host));assertFalse("detached",cooking.getKeepScreenOn());}
 @Test public void senderAndMessageHaveDifferentViewsAndSpacing()throws Exception{JSONObject snap=snapshot();String key=Library.id(snap.getJSONObject("recipe"));host.getSharedPreferences("sous-chef",0).edit().putString(key,"[{\"role\":\"user\",\"content\":\"На каком огне?\"},{\"role\":\"assistant\",\"content\":\"На среднем. Если томаты прилипают — уменьшите нагрев.\"}]").commit();new SousChefSheet(host,snap,()->0,()->0).show();Dialog d=org.robolectric.shadows.ShadowDialog.getLatestDialog();View root=d.getWindow().getDecorView();TextView sender=find(root,"Вы"),message=find(root,"На каком огне?");assertNotNull(sender);assertNotNull(message);assertNotSame(sender,message);assertTrue(((LinearLayout.LayoutParams)message.getLayoutParams()).topMargin>0);screenshot(root,"chat-messages");d.dismiss();}
 @Test public void detailShowsHonestPartialPriceAndFacts()throws Exception{Method m=MainActivity.class.getDeclaredMethod("openRecipe",JSONObject.class,String.class);m.setAccessible(true);m.invoke(host,snapshot(),"choices");View root=host.getWindow().getDecorView();assertNotNull(find(root,"Стоимость рассчитана частично"));assertNotNull(find(root,"Есть 2 из 2 ингредиентов · + базовые · Просто"));screenshot(root,"recipe-facts");}
}
